import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

const registerWeatherTool = (
  registry: ToolRegistry,
  execute: (input: Record<string, unknown>) => Promise<string>
): void => {
  registry.register(
    {
      name: 'echo_weather',
      description: 'Echo weather input',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    execute
  );
};

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('passes valid input with an extra property through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async (input: Record<string, unknown>) => JSON.stringify(input));
    registerWeatherTool(registry, executor);

    const input = {location: 'Paris', traceId: 'request-123'};
    const response = await registry.execute('echo_weather', input);

    expect({response, calls: executor.mock.calls}).toEqual({
      response: {result: JSON.stringify(input)},
      calls: [[input, undefined]],
    });
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('compiles a static tool schema once across ten executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      const executor = jest.fn(async () => 'ok');
      registerWeatherTool(registry, executor);

      for (let index = 0; index < 10; index += 1) {
        await registry.execute('echo_weather', {location: 'Paris'});
      }

      const compileCallRecords = compile.mock.calls;
      const executorCallRecords = executor.mock.calls;
      const compileCalls = compileCallRecords.length;
      const executorCalls = executorCallRecords.length;
      expect({compileCalls, executorCalls}).toEqual({
        compileCalls: 1,
        executorCalls: 10,
      });
    } finally {
      compile.mockRestore();
    }
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('rejects a wrong-typed property with its field path and expected type', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'unreachable');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('echo_weather', {location: 42});

    const executorCalls = executor.mock.calls;
    expect({result: response.result, calls: executorCalls.length}).toEqual({
      result: 'location must be string',
      calls: 0,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('logs a safe validation rejection with its field path and failed constraint', async () => {
    const records: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>) =>
      records.push({category, message, fields});
    const logger: Logger = {debug: record, info: record, warn: record, error: record};
    setLogger(logger);

    const registry = new ToolRegistry();
    registerWeatherTool(registry, async () => 'unreachable');

    await registry.execute('echo_weather', {location: 42});

    expect(records).toEqual([
      expect.objectContaining({
        message: 'tool input rejected',
        fields: expect.objectContaining({path: 'location', keyword: 'type'}),
      }),
    ]);
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('logs a required-property rejection with its field path and constraint', async () => {
    const records: Array<{message: string; fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: (_category, message, fields) => records.push({message, fields}),
      info: (_category, message, fields) => records.push({message, fields}),
      warn: (_category, message, fields) => records.push({message, fields}),
      error: (_category, message, fields) => records.push({message, fields}),
    });

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'echo_weather',
        description: 'Echo weather input',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'unreachable'
    );

    await registry.execute('echo_weather', {});

    expect(records).toEqual([
      expect.objectContaining({
        message: 'tool input rejected',
        fields: expect.objectContaining({path: 'location', keyword: 'required'}),
      }),
    ]);
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('names the enum constraint when an input value is not allowed', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'forecast_units',
        description: 'Choose forecast units',
        inputSchema: {
          type: 'object',
          properties: {units: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['units'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('forecast_units', {units: 'kelvin'});

    expect(response.result).toBe('units failed the enum constraint');
  });

  // spec: specs/hal-engine-tool-input-validation#7
  it('names nested property paths with dots in validation failures', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_weather',
        description: 'Validate nested weather input',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('nested_weather', {location: {city: 42}});

    expect(response.result).toBe('location.city must be string');
  });

  // spec: specs/hal-engine-tool-input-validation#5
  it('validates a function-valued definition against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    registry.register(
      () => {
        definitionCalls += 1;
        const required = definitionCalls === 1 ? 'location' : 'city';
        return {
          name: 'dynamic_weather',
          description: 'Validate changing weather input',
          inputSchema: {
            type: 'object',
            properties: {[required]: {type: 'string'}},
            required: [required],
          },
        };
      },
      async input => JSON.stringify(input)
    );

    const response = await registry.execute('dynamic_weather', {city: 'Paris'});

    expect(response).toEqual({result: JSON.stringify({city: 'Paris'})});
  });
});
import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

type ValidationError = ErrorObject & {instancePath?: string; dataPath?: string};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${(error as Error).message}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compile(schema: Record<string, unknown>): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.ajv.compile(schema);
    this.validators.set(schema, validator);
    return validator;
  }

  private errorParams(error: ValidationError): {missingProperty?: string; type?: string} {
    return error.params as {missingProperty?: string; type?: string};
  }

  private formatErrorPath(error: ValidationError): string {
    const path =
      (error.instancePath || error.dataPath || '/').replace(/^\//, '').replace(/^\./, '').replace(/\//g, '.') || '/';
    if (error.keyword === 'required') {
      const missingProperty = this.errorParams(error).missingProperty;
      return missingProperty ? (path === '/' ? missingProperty : `${path}.${missingProperty}`) : path;
    }
    return path;
  }

  private validationResult(validator: ValidateFunction, input: Record<string, unknown>): ToolResponse | undefined {
    if (validator(input)) return undefined;
    const error = validator.errors?.[0] as ValidationError | undefined;
    if (!error) return {result: 'Tool input does not match the registered input schema.'};
    const path = this.formatErrorPath(error);
    const params = this.errorParams(error);
    if (error.keyword === 'required') {
      return {result: `${path} is required`};
    }
    if (error.keyword === 'type') {
      return {result: `${path} must be ${String(params.type)}`};
    }
    if (error.keyword === 'enum') {
      return {result: `${path} failed the enum constraint`};
    }
    return {result: `${path} failed the ${error.keyword} constraint`};
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Input rejections return a ToolResponse; only unknown tool names throw. See specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.compile(definition.inputSchema);
    const rejection = this.validationResult(validator, input);
    if (rejection) {
      const error = validator.errors?.[0] as ValidationError | undefined;
      log.warn('tool', 'tool input rejected', {
        path: error ? this.formatErrorPath(error) : '/',
        keyword: error?.keyword ?? 'schema',
      });
      return rejection;
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L17)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L48), [validated by rejects a wrong-typed property with its field path and expected type](../../src/orchestration/tools/registry.test.ts#L69), [validated by logs a safe validation rejection with its field path and failed constraint](../../src/orchestration/tools/registry.test.ts#L84)). Rejection logs name the failing property path and constraint ([validated by logs a required-property rejection with its field path and constraint](../../src/orchestration/tools/registry.test.ts#L105)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by passes valid input with an extra property through to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L31)). A rejected enum value is reported with its field path and the `enum` constraint ([validated by names the enum constraint when an input value is not allowed](../../src/orchestration/tools/registry.test.ts#L139)).
- Validation failures identify nested property paths with dot-separated field names ([validated by names nested property paths with dots in validation failures](../../src/orchestration/tools/registry.test.ts#L162)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L96)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by compiles a static tool schema once across ten executions](../../src/orchestration/tools/registry.test.ts#L46)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by validates a function-valued definition against the schema returned for each call](../../src/orchestration/tools/registry.test.ts#L188)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L114)).
