     8	Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.
     9	
    10	## Validation at execute time
    11	
    12	- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L17)).
    13	- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L48), [validated by rejects a wrong-typed property with its field path and expected type](../../src/orchestration/tools/registry.test.ts#L69), [validated by logs a safe validation rejection with its field path and failed constraint](../../src/orchestration/tools/registry.test.ts#L84)). Rejection logs name the failing property path and constraint ([validated by logs a required-property rejection with its field path and constraint](../../src/orchestration/tools/registry.test.ts#L105)).
    14	- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by passes valid input with an extra property through to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L31)). A rejected enum value is reported with its field path and the `enum` constraint ([validated by names the enum constraint when an input value is not allowed](../../src/orchestration/tools/registry.test.ts#L139)).
    15	- Validation failures identify nested property paths with dot-separated field names ([validated by names nested property paths with dots in validation failures](../../src/orchestration/tools/registry.test.ts#L162)).
    16	- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.
    17	
    18	## Schema compilation and caching
    19	
    20	- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L96)).
    21	- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by compiles a static tool schema once across ten executions](../../src/orchestration/tools/registry.test.ts#L46)).
    22	- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by validates a function-valued definition against the schema returned for each call](../../src/orchestration/tools/registry.test.ts#L188)).
    23	
    24	## Orchestrator tool-loop recovery
    25	
    26	- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L114)).

import {readdirSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {scriptRunner} from './helpers/script-runner.js';

const root = process.cwd();
const script = join(root, 'scripts', 'check-spec-links.mjs');

const trailingSpec = 'scripts/fixtures/spec-links/trailing/spec.md';
const misplacedSpec = 'scripts/fixtures/spec-links/misplaced/spec.md';
const citedTest = '../../../../tests/check-at-pass.test.ts';
const trailingZeroSummary = 'misplaced: 0 across 0 specs (9 statements scanned)\n';

type Finding = {
  spec: string;
  line: number | null;
  path: string;
  anchorLine: number | null;
  label: string;
  statement: string;
};

const {run, runFrom} = scriptRunner(script);

const findings = (...args: string[]): Finding[] => JSON.parse(run('--json', ...args).stdout);

const discoveredSpecs = (): string[] => {
  const slugs = readdirSync(join(root, 'specs'), {withFileTypes: true})
    .filter(entry => entry.isDirectory())
    .map(entry => entry.name)
    .sort();

  return [...slugs.map(slug => `specs/${slug}/spec.md`), '.specify/spec.md'];
};

describe('check-spec-links', () => {
  it("a list item with two mid-item citations reports both at the item's line", () => {
    expect(findings(misplacedSpec).filter(finding => finding.line === 10)).toMatchObject([
      {anchorLine: 14, path: citedTest},
      {anchorLine: 22, path: citedTest},
    ]);
  });

  it("a mid-sentence citation in a paragraph reports one finding at the paragraph's line", () => {
    expect(findings(misplacedSpec).filter(finding => finding.line === 16)).toMatchObject([
      {
        anchorLine: 38,
        statement:
          'The lamp turns clockwise ' +
          '([validated by](../../../../tests/check-at-pass.test.ts#L38)) once every minute.',
      },
    ]);
  });

  it('a citation with no #L anchor is reported with the path alone', () => {
    expect(run(misplacedSpec).stdout).toContain(
      `${misplacedSpec}:20: ${citedTest} cited outside the statement's trailing parenthetical`
    );
  });

  it('a paragraph sentence whose citation is trailing reports nothing', () => {
    expect(run(trailingSpec).stdout).toBe(trailingZeroSummary);
  });

  it('a mid-sentence link to a script rather than a test reports nothing', () => {
    expect(run(trailingSpec).stdout).toBe(trailingZeroSummary);
  });

  it('a citation written inside backticks reports nothing', () => {
    expect(run(trailingSpec).stdout).toBe(trailingZeroSummary);
  });

  it('a spec citing only in trailing parentheticals exits 0 with a zero summary', () => {
    const result = run(trailingSpec);

    expect(result).toMatchObject({status: 0, stdout: trailingZeroSummary});
  });

  it('a spec with misplaced citations exits 1 and summarises findings, specs and statements', () => {
    const result = run(misplacedSpec, trailingSpec);

    expect(result).toMatchObject({
      status: 1,
      stdout: expect.stringContaining('misplaced: 4 across 1 specs (17 statements scanned)'),
    });
  });

  it('--json prints only an array of findings carrying every reported field', () => {
    const result = run('--json', misplacedSpec);

    expect({summarised: result.stdout.includes('misplaced:'), first: JSON.parse(result.stdout)[0]}).toEqual({
      summarised: false,
      first: {
        spec: misplacedSpec,
        line: 10,
        path: citedTest,
        anchorLine: 14,
        label: 'validated by',
        statement: expect.stringContaining('The beacon clamps its range'),
      },
    });
  });

  it('an unknown flag exits 2 with the usage line', () => {
    const result = run('--frobnicate');

    expect(result).toMatchObject({
      status: 2,
      stdout: '',
      stderr: expect.stringContaining('usage: check-spec-links.mjs [--json] [spec-path ...]'),
    });
  });

  it('the usage line says paths resolve against the repo root', () => {
    expect(run('--frobnicate').stderr).toContain('spec paths resolve against the repo root, not the working directory');
  });

  it('a spec path that cannot be read exits 2 naming the path', () => {
    const result = run('scripts/fixtures/spec-links/absent/spec.md');

    expect(result).toMatchObject({
      status: 2,
      stderr: expect.stringContaining('cannot read spec scripts/fixtures/spec-links/absent/spec.md'),
